    public boolean countsClaimed(Claim claim) {
        ClaimStatus status = claim.getStatus();
        if (status == null || !status.counts() || claim.isDeferred()) return false;
        if (!status.isOpen() || !retiredOut()) return true;
        return claim.isStated();
    }

